pi(10000, 3.141592653590042).

clause(1,
       pi(var('A'), var('B')),
       (pi(1, var('A'), 0, var('C'), 1), var('B') is 3 + 4 * var('C'))).
clause(2, pi(var('A'), var('A'), var('B'), var('B'), anonymous(1)), !).
clause(3,
       pi(var('A'), var('B'), var('C'), var('D'), var('E')),
       (var('F') is var('A') + 1,
        var('L') is var('C') + var('E') / (2 * var('A') * (2 * var('A') + 1) * (2 * var('A') + 2)),
        var('M') is - var('E'),
        pi(var('F'), var('B'), var('L'), var('D'), var('M')))).

